// 测试用最小 CM6 view 模拟
class DecorationSet {
  constructor(ranges) { this.ranges = ranges || []; }
  map() { return this; }
  update(u) {
    let rs = this.ranges.slice();
    if (u.filter) rs = rs.filter((r) => u.filter(r.from, r.to, r.deco));
    if (u.add) rs = rs.concat(u.add.map((d) => ({ from: d.from, to: d.to, deco: d.deco })));
    return new DecorationSet(rs);
  }
  between(a, b, cb) { this.ranges.forEach((r) => cb(r.from, r.to, r.deco)); }
}
const NONE = new DecorationSet([]);

const Decoration = {
  none: NONE,
  mark(spec) { return { spec, range: (from, to) => ({ from, to, deco: { spec } }) }; },
  widget(spec) { return { spec, range: (at) => ({ from: at, to: at, deco: { spec } }) }; },
};

const EditorView = {
  decorations: { from: (f) => ({ __from: true, f }) },
  // 测试辅助
};

class WidgetType {}
module.exports = { Decoration, DecorationSet, EditorView, WidgetType };

